<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$bajo=$mysqli->query('SELECT codigo,nombre,stock,stock_minimo FROM productos WHERE activo=1 AND stock<=stock_minimo ORDER BY stock ASC,nombre');
$vence=$mysqli->query("SELECT p.codigo,p.nombre,l.numero_lote,l.fecha_vencimiento,l.cantidad_disponible FROM lotes_producto l JOIN productos p ON p.id=l.producto_id WHERE l.cantidad_disponible>0 AND l.fecha_vencimiento IS NOT NULL AND l.fecha_vencimiento<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) ORDER BY l.fecha_vencimiento");
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alertas de inventario</title><style>body{font:15px Arial;background:#f2f7f5;color:#243b37;margin:0}.wrap{padding:22px}.box{background:white;padding:20px;border-radius:12px;margin-bottom:16px}h1,h2{color:#087f73}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}th{background:#eaf5f1}.btn{background:#087f73;color:white;padding:10px 14px;border-radius:7px;text-decoration:none}</style></head><body><main class="wrap"><h1>Alertas de inventario</h1><p><a class="btn" href="index.php">Volver</a> <a class="btn" href="compras.php">Registrar compra</a></p><section class="box"><h2>Stock bajo o agotado</h2><table><thead><tr><th>Código</th><th>Medicamento</th><th>Stock actual</th><th>Mínimo</th></tr></thead><tbody><?php while($p=$bajo->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($p['codigo'])?></td><td><?=htmlspecialchars($p['nombre'])?></td><td><?=(int)$p['stock']?></td><td><?=(int)$p['stock_minimo']?></td></tr><?php } ?></tbody></table></section><section class="box"><h2>Lotes vencidos o próximos a vencer (60 días)</h2><table><thead><tr><th>Medicamento</th><th>Lote</th><th>Vencimiento</th><th>Unidades</th></tr></thead><tbody><?php while($l=$vence->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($l['nombre'])?></td><td><?=htmlspecialchars($l['numero_lote'])?></td><td><?=htmlspecialchars($l['fecha_vencimiento'])?></td><td><?=(int)$l['cantidad_disponible']?></td></tr><?php } ?></tbody></table></section></main></body></html>
